/*
Instruction Memory (Program Memory)
- Stores instructions
- Inputs and Outputs
    - address: Given by program counter to get instruction at memory location
    - instruction: Instruction at pc address
*/
module instruction_memory(
    input wire clk,
    input wire [31:0] address,
    output wire [31:0] instruction
);
    wire [7:0] mem_index;
    assign mem_index = address[9:2];

    // -------------------------------------------------------------------------
    // ASIC SRAM Macro Instantiation
    // Replace "sram_256x32" with the exact name generated by your Memory Compiler
    // -------------------------------------------------------------------------
    sram_256x32 u_imem_sram (
        .clk  (clk),
        .addr (mem_index),       // 8-bit address for 256 words
        .din  (32'b0),           // Tie input data to zero (Read-Only Memory)
        .wen  (1'b0),            // Write Enable disabled
        .dout (instruction)      // Direct connection to CPU pipeline
    );

    // Simulation-only preload block (Ignored by the ASIC synthesis engine)
    `ifdef SIMULATION
    initial begin
        // Use your EDA tool's hierarchical system task to force the memory contents
        $readmemh("program_code.txt", u_imem_sram.internal_memory_array);
    end
    `endif
endmodule

module sram_256x32(
    input wire clk,
    input wire [7:0] addr,
    input wire [31:0] din,
    input wire wen,
    output reg [31:0] dout
);
    reg [31:0] internal_memory_array [255:0];
    always @(posedge clk) begin
        if (wen) begin
            internal_memory_array[addr] <= din;
        end
    end

    always @(*) begin
        dout = internal_memory_array[addr];
    end
endmodule